import { ChatThread, Button, type ChatMessage } from "march/ui"

// bir robotla hızlı yanıt sohbeti: bir düğmeye bas, robot "yazıyor…" der ve yanıt verir
const ANSWERS: Record<string, string> = {
  "Merhaba 👋": "Bip bop! Merhaba insan 🤖",
  "Hava nasıl?": "Sunucu odası her zaman 18 derece ❄️",
  "Bir şaka yap": "Neden robotlar hiç korkmaz? Çünkü sinirleri yok, kabloları var ⚡",
}

export function RobotChat() {
  let $messages: ChatMessage[] = [{ id: "r0", senderName: "Robo", text: "Bir şey sor bakalım!", time: new Date() }]
  let $typing: string[] = []
  let n = 0
  const ask = (q: string) => {
    $messages = [...$messages, { id: `q${++n}`, mine: true, text: q, time: new Date(), status: "read" }]
    $typing = ["Robo"]
    setTimeout(() => { $typing = []; $messages = [...$messages, { id: `a${n}`, senderName: "Robo", text: ANSWERS[q], time: new Date() }] }, 900)
  }
  return <div sx={{ flex: "col", gap: 2 }}>
    <ChatThread messages={$messages} typing={$typing} days={false} label="Robo ile sohbet" />
    <div sx={{ flex: ["row", "wrap"], gap: 1 }}>
      {Object.keys(ANSWERS).map((q) => <Button size="sm" variant="ghost" disabled={$typing.length > 0} on:click={() => ask(q)}>{q}</Button>)}
    </div>
  </div>
}

import { ChatThread, ChatComposer, type ChatMessage } from "march/ui"

// bir destek sohbeti: gönderilen mesaj gidiyor → iletildi → okundu olur; her üç mesajdan biri bağlantı hatası verir
// (Yeniden dene); bir balona tepki bırakılır ya da yanıtlanır (yanıt satırı yazma kutusunun üstüne gelir)
const ago = (min: number) => new Date(Date.now() - min * 60_000)

export function SupportChat() {
  let $messages: ChatMessage[] = [
    { id: "s1", senderName: "Destek · Ayşe", text: "Merhaba! Siparişinizle ilgili nasıl yardımcı olabilirim?", time: ago(12) },
    { id: "s2", mine: true, text: "Kargom 3 gündür aynı şubede görünüyor.", time: ago(10), status: "read" },
    { id: "s3", senderName: "Destek · Ayşe", text: "Kontrol ediyorum, bir dakika lütfen 🙏", time: ago(9), reactions: [{ emoji: "👍", count: 1, mine: true }] },
  ]
  let $reply = null as ChatMessage | null
  let n = 0
  const patch = (id: string, p: Partial<ChatMessage>) => { $messages = $messages.map((m) => (m.id === id ? { ...m, ...p } : m)) }
  const deliver = (id: string) => {
    setTimeout(() => patch(id, { status: "delivered" }), 500)
    setTimeout(() => patch(id, { status: "read" }), 1200)
  }
  const send = (text: string) => {
    const id = `u${++n}`
    const reply = $reply ? { name: $reply.mine ? "Siz" : $reply.senderName ?? "", text: $reply.text ?? "" } : undefined
    $messages = [...$messages, { id, mine: true, text, time: new Date(), status: "sending", reply }]
    $reply = null
    if (n % 3 === 0) setTimeout(() => patch(id, { status: "failed" }), 400); else deliver(id)
  }
  const react = (m: ChatMessage, emoji: string) => {
    const mine = m.reactions?.find((r) => r.mine)
    const rest = (m.reactions ?? []).filter((r) => !r.mine)
    patch(m.id, { reactions: mine?.emoji === emoji ? rest : [...rest, { emoji, count: 1, mine: true }] })
  }
  return <div sx={{ flex: "col", gap: 2 }}>
    <ChatThread messages={$messages} label="Destek sohbeti" jumpColor="brand-green"
      onReact={react} onReply={(m) => $reply = m} onRetry={(m) => { patch(m.id, { status: "sending" }); deliver(m.id) }} />
    <ChatComposer onSend={send} placeholder="Mesajınız"
      replyTo={$reply ? { name: $reply.mine ? "Siz" : $reply.senderName ?? "", text: $reply.text ?? "" } : null}
      onCancelReply={() => $reply = null} />
  </div>
}

import { ChatThread, Button, Badge, type ChatMessage } from "march/ui"

// ChatThread'in bütün özellikleri: mesajlar (yanıt, tepki, düzenlendi, resim, durumlar), yazanlar, grup sohbeti,
// tepki / yanıt / yeniden dene olayları, mesaj kümesi süresi (runMinutes), erişilebilir ad, kendi gün ayracı,
// kendi "N yeni" düğmesi ve rengi, hareket ve sınıf
const PHOTO = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42mP4WSz2xmMmQ43VWzlpbwAsKgV3rhVt4wAAAABJRU5ErkJggg=="
const at = (d: number, h: number, m: number) => { const x = new Date(); x.setDate(x.getDate() - d); x.setHours(h, m, 0, 0); return x }

export function ChatThreadLab() {
  let $messages: ChatMessage[] = [
    { id: "a1", senderId: "ece", senderName: "Ece", text: "Akşam yemeği kimde?", time: at(2, 19, 0) },
    { id: "a2", senderId: "ece", senderName: "Ece", text: "Ben tatlı getiririm 🍰", time: at(2, 19, 9) },
    { id: "a3", senderId: "can", senderName: "Can", text: "Bende! Gün batımı da harika", time: at(1, 18, 30), image: { src: PHOTO, alt: "Gün batımı" }, edited: true },
    { id: "a4", mine: true, text: "Geliyorum", time: at(0, 9, 0), status: "read", reply: { name: "Can", text: "Bende!" }, reactions: [{ emoji: "🎉", count: 2 }] },
    { id: "a5", mine: true, text: "Bu mesaj gidemedi", time: at(0, 9, 1), status: "failed" },
  ]
  let $typing: string[] = ["Ece"]
  let $group = true
  let $log = "-"
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button size="sm" variant="ghost" on:click={() => $group = !$group}>{$group ? "Birebir" : "Grup"}</Button>
      <Button size="sm" variant="ghost" on:click={() => $typing = $typing.length ? [] : ["Ece", "Can"]}>Yazıyor</Button>
      <Badge tone="primary">{$log}</Badge>
    </div>
    <ChatThread class="lab-chat" label="Akşam yemeği" messages={() => $messages} typing={() => $typing} group={() => $group}
      runMinutes={10} motion={false} jumpColor="brand-pink" jump={(c) => `⬇ ${c} yeni mesaj`}
      days={(d) => d.toLocaleDateString("tr-TR", { weekday: "long" })}
      onReact={(m, e) => { $messages = $messages.map((x) => (x.id === m.id ? { ...x, reactions: [...(x.reactions ?? []), { emoji: e, count: 1, mine: true }] } : x)); $log = `tepki ${e}` }}
      onReply={(m) => $log = `yanıt: ${m.text}`}
      onRetry={(m) => { $messages = $messages.map((x) => (x.id === m.id ? { ...x, status: "sent" } : x)); $log = "yeniden gönderildi" }} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ChatThreadLab } from "./ChatThreadLab.tsx"

// ChatThreadLab'in testleri: kaydedince Testler sekmesinde çalışır
test("grup sohbetinde gönderenin adı görünür", () => {
  const s = renderTest(() => <ChatThreadLab />)
  expect(s.sees("Ece")).toBe(true)
  expect(s.sees("Akşam yemeği kimde?")).toBe(true)
})

test("gidemeyen mesajın Yeniden dene düğmesi onRetry'ı çalıştırır", async () => {
  const s = renderTest(() => <ChatThreadLab />)
  const retry = s.get(".lab-chat .m-msg-retry")
  expect(retry).toBeTruthy()
  await s.click(retry!)
  expect(s.get(".lab-chat .m-msg-retry")).toBe(null)
  expect(s.sees("yeniden gönderildi")).toBe(true)
})

test("yanıt, tepki ve düzenlendi işaretleri balonlarda görünür", () => {
  const s = renderTest(() => <ChatThreadLab />)
  expect(s.sees("🎉")).toBe(true)
  expect(s.sees("Bende!")).toBe(true)
})

test("yazanlar düğmesi yazıyor satırını açar ve kapar", async () => {
  const s = renderTest(() => <ChatThreadLab />)
  const before = s.text()
  await s.click("Yazıyor")
  expect(s.text() === before).toBe(false)
})
